    o_write = 'w' if (owner & 0o2) else '-'
    if setuid:
        o_execute = 's' if (owner & 0o1) else 'S'
    else:
        o_execute = 'x' if (owner & 0o1) else '-'
    parts.append(f"{o_read}{o_write}{o_execute}")

    # Group part
    g_read = 'r' if (group & 0o4) else '-'
    g_write = 'w' if (group & 0o2) else '-'
    if setgid:
        g_execute = 's' if (group & 0o1) else 'S'
    else:
        g_execute = 'x' if (group & 0o1) else '-'
    parts.append(f"{g_read}{g_write}{g_execute}")

    # Others part
    oth_read = 'r' if (others & 0o4) else '-'
    oth_write = 'w' if (others & 0o2) else '-'
    if sticky:
        oth_execute = 't' if (others & 0o1) else 'T'
    else:
        oth_execute = 'x' if (others & 0o1) else '-'
