def expand_tabs(line, width):
    if not isinstance(line, str) or '\n' in line or '\r' in line:
        raise ValueError
    if not isinstance(width, int) or width < 1 or width > 32:
        raise ValueError
    result = []
    current_pos = 0
    for c in line:
        if c == '\t':
            next_stop = ((current_pos // width) + 1) * width
            spaces = next_stop - current_pos
            result.append(' ' * spaces)
            current_pos = next_stop
        else:
            result.append(c)
            current_pos += 1
    return ''.join(result)

def collapse_spaces(line, width):
    if not isinstance(line, str) or '\n' in line or '\r' in line or '\t' in line:
        raise ValueError
    if not isinstance(width, int) or width < 1 or width > 32:
        raise ValueError
    result = []
    for i in range(0, len(line), width):
        chunk = line[i:i+width]
        if len(chunk) == width:
            trailing = 0
            for c in reversed(chunk):
                if c == ' ':
                    trailing += 1
                else:
                    break
            if trailing >= 2:
                chunk = chunk[:-trailing] + '\t'
        result.append(chunk)
    return ''.join(result)

