    def is_token(s):
        allowed = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!#$%&\'*+-.^_`|~')
        return all(c in allowed for c in s) and len(s) > 0

    def parse_quoted_string(s):
        if len(s) < 2 or s[0] != '"' or s[-1] != '"':
            raise ValueError
        inner = s[1:-1]
        result = []
        i = 0
        while i < len(inner):
            c = inner[i]
            if c == '\\':
                if i == len(inner) - 1:
                    raise ValueError
                next_c = inner[i+1]
                if next_c == '"':
                    result.append('"')
                    i += 2
                elif next_c == '\\':
                    result.append('\\')
                    i += 2
                else:
                    raise ValueError
            else:
                if ord(c) < 32 or ord(c) > 127:
                    raise ValueError
                result.append(c)
                i += 1
        return ''.join(result)

    parts = [p.strip() for p in value.split(';')]
    if not parts:
        raise ValueError
    mediatype_part = parts[0].strip()
    if not mediatype_part:
        raise ValueError
    if '/' not in mediatype_part or mediatype_part.count('/') != 1:
        raise ValueError
    type_, subtype = mediatype_part.split('/', 1)
    if not is_token(type_) or not is_token(subtype):
        raise ValueError
    mediatype = f"{type_.lower()}/{subtype.lower()}"
    params = {}
    for part in parts[1:]:
        part = part.strip()
        if not part:
