        if name_lower in params:
            raise ValueError
        if value_part.startswith('"'):
            value = parse_quoted_string(value_part)
        else:
            if not is_token(value_part):
                raise ValueError
            value = value_part
        params[name_lower] = value
    return (mediatype, params)

