def number_headings(lines):
    counts = [0] * 6  # For levels 1 to 6
    prev_level = None
    result = []
    for line in lines:
        if not isinstance(line, str):
            raise ValueError
        parts = line.split(' ', 1)
        if len(parts) != 2:
            raise ValueError
        hashes, title = parts
        if not (1 <= len(hashes) <= 6) or not all(c == '#' for c in hashes):
            raise ValueError
        if not title or title[0] == ' ' or title[-1] == ' ' or '\n' in title:
            raise ValueError
