        if prev_level is not None:
            if level > prev_level + 1:
                raise ValueError
        else:
            if level != 1:
                raise ValueError
        number_parts = []
        for i in range(level - 1):
            number_parts.append(str(counts[i]))
        next_num = counts[level - 1] + 1
        number_parts.append(str(next_num))
        number_str = '.'.join(number_parts)
        for i in range(level - 1, 6):
            counts[i] = 0
        counts[level - 1] += 1
        result.append(f"{number_str} {title}")
        prev_level = level
    return result

