    if not isinstance(limit, int) or isinstance(limit, bool) or not (1 <= limit <= 1000):
        raise ValueError

    # Helper function to compute sum of proper divisors
    def sum_proper_divisors(m):
        if m <= 1:
            return 0
        total = 1
        sqrt_m = int(m ** 0.5)
        for i in range(2, sqrt_m + 1):
            if m % i == 0:
                j = m // i
                if i == j:
                    total += i
                else:
                    total += i + j
        return total

    terms = [n]
    kind = "unknown"

    for _ in range(limit):
        last = terms[-1]
        t = sum_proper_divisors(last)

        if t == 0:
            terms.append(t)
            kind = "terminates"
            break

        if t in terms:
            index = terms.index(t)
            L = len(terms) - index
            if index == 0:
                if L == 1:
                    kind = "perfect"
                elif L == 2:
                    kind = "amicable"
                else:
                    kind = "sociable"
            else:
                if L == 1:
                    kind = "aspiring"
                else:
                    kind = "cyclic"
            break

        if t > 1e9:
            kind = "unknown"
            break

        terms.append(t)

    else:
        # Loop completed without breaking, kind remains 'unknown'
        pass

    return (kind, terms)

import math

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    w = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i += w
        w = 6 - w
    return True

def factor(n):
    factors = {}
    while n % 2 == 0:
        factors[2] = factors.get(2, 0) + 1
        n = n // 2
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors[i] = factors.get(i, 0) + 1
            n = n // i
        i += 2
    if n > 1:
        factors[n] = 1
    return factors

def euler_phi(n):
    if n == 0:
        return 0
    if n == 1:
        return 1
    factors = factor(n)
    result = 1
    for p, exp in factors.items():
        result *= (p - 1) * (p ** (exp - 1))
    return result

def count_primitive_roots(n):
    if not isinstance(n, int) or n < 2 or n > 10**10:
        raise ValueError
    factors_n = factor(n)
    if not factors_n:
        return 0
    if n == 2 or n == 4:
        return 1
    if len(factors_n) == 1:
        p = next(iter(factors_n))
        exponent = factors_n[p]
        if p == 2:
            if exponent > 2:
                return 0
            else:
                phi_n = euler_phi(n)
                return euler_phi(phi_n)
        else:
            if is_prime(p):
                phi_n = euler_phi(n)
                return euler_phi(phi_n)
            else:
                return 0
    elif len(factors_n) == 2:
        if 2 in factors_n and factors_n[2] == 1:
            other = [p for p in factors_n if p != 2]
            if len(other) != 1:
                return 0
            p = other[0]
            if is_prime(p):
                phi_n = euler_phi(n)
                return euler_phi(phi_n)
            else:
                return 0
        else:
            return 0
    else:
        return 0

def smallest_primitive_root(n):
    if not isinstance(n, int) or n < 2 or n > 10**10:
        raise ValueError
    if count_primitive_roots(n) == 0:
        return None
    if n == 2:
        return 1
    if n == 4:
        return 3
    phi_n = euler_phi(n)
    factors_phi = factor(phi_n)
    primes_phi = list(factors_phi.keys())
    for g in range(2, n):
        if math.gcd(g, n) != 1:
            continue
        is_primitive = True
        for q in primes_phi:
            if pow(g, phi_n // q, n) == 1:
                is_primitive = False
                break
        if is_primitive:
            return g
    return None

