def get_divisors(factors):
    divisors = {1}
    for p in factors:
        exponents = [p**e for e in range(1, factors[p]+1)]
        current_divisors = list(divisors)
        for d in current_divisors:
            for exp in exponents:
                new_d = d * exp
                divisors.add(new_d)
