def consecutive_sums(n):
    if not isinstance(n, int) or isinstance(n, bool) or n < 1 or n > 10**12:
        raise ValueError
    x = 2 * n
    factors = factorize(x)
    divisors = get_divisors(factors)
    runs = []
    for m in divisors:
        if m < 2:
            continue
        temp = (x // m) - m + 1
        if temp <= 0:
            continue
        if temp % 2 != 0:
            continue
        a = temp // 2
        if a <= 0:
            continue
        b = a + m - 1
        runs.append((a, b))
    runs.sort()
    return runs

