from collections import deque

def lca_answers(parent, queries):
    n = len(parent)
    if n == 0:
        if not queries:
            return []
        else:
            raise ValueError

    for p in parent:
        if not isinstance(p, int) or isinstance(p, bool):
            raise ValueError

    roots = [i for i, p in enumerate(parent) if p == -1]
    if len(roots) != 1:
        raise ValueError
    root = roots[0]

    for v in range(n):
        p = parent[v]
        if v == root:
            if p != -1:
                raise ValueError
        else:
            if p == -1 or p < 0 or p >= n:
                raise ValueError

    children = [[] for _ in range(n)]
    for v in range(n):
        if v != root:
            p = parent[v]
            children[p].append(v)

    visited = set()
    queue = deque([root])
    visited.add(root)
    while queue:
        u = queue.popleft()
        for v in children[u]:
            if v not in visited:
                visited.add(v)
                queue.append(v)
    if len(visited) != n:
        raise ValueError

    depth = [0] * n
    queue = deque([root])
    while queue:
        u = queue.popleft()
        for v in children[u]:
            depth[v] = depth[u] + 1
            queue.append(v)

    max_level = 15
    up = [[0] * n for _ in range(max_level)]
    for u in range(n):
        if u == root:
            up[0][u] = u
        else:
            up[0][u] = parent[u]
    for j in range(1, max_level):
        for u in range(n):
            up[j][u] = up[j-1][up[j-1][u]]

    result = []
    for q in queries:
        if not isinstance(q, (list, tuple)) or len(q) != 2:
            raise ValueError
        u, v = q
        if not isinstance(u, int) or isinstance(u, bool):
            raise ValueError
