def maze_steps(grid):
    # Validate the grid
    if not grid:
        raise ValueError
    rows = len(grid)
    if rows < 1 or rows > 30:
        raise ValueError
    cols = len(grid[0])
    if cols < 1 or cols > 30:
        raise ValueError
    for row in grid:
        if len(row) != cols:
            raise ValueError
        for c in row:
            if c not in {'#', '.', 'S', 'E', 'a', 'b', 'c', 'd', 'A', 'B', 'C', 'D'}:
                raise ValueError

    # Find start and exit positions
    start = None
    exit_pos = None
    for i in range(rows):
        for j in range(cols):
            c = grid[i][j]
            if c == 'S':
                if start is not None:
                    raise ValueError
                start = (i, j)
            elif c == 'E':
                if exit_pos is not None:
                    raise ValueError
                exit_pos = (i, j)

    if start is None or exit_pos is None:
        raise ValueError

    # Initialize BFS
    visited = set()
    queue = deque()
    start_row, start_col = start
    initial_keys = 0
    queue.append((start_row, start_col, initial_keys, 0))
    visited.add((start_row, start_col, initial_keys))

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        row, col, keys, steps = queue.popleft()

        # Check if current position is the exit
        if (row, col) == exit_pos:
            return steps

        for dr, dc in directions:
            new_row = row + dr
            new_col = col + dc
            if 0 <= new_row < rows and 0 <= new_col < cols:
                cell = grid[new_row][new_col]
                if cell == '#':
                    continue  # Wall, can't move here

                # Check if it's a door
                if cell in 'ABCD':
                    required_key = cell.lower()
                    key_bit = 1 << (ord(required_key) - ord('a'))
                    if not (keys & key_bit):
                        continue  # Don't have the key, can't open

                # Determine new keys
                if cell in 'abcd':
                    new_keys = keys | (1 << (ord(cell) - ord('a')))
                else:
                    new_keys = keys

                # Check if this state has been visited
                if (new_row, new_col, new_keys) not in visited:
                    visited.add((new_row, new_col, new_keys))
                    queue.append((new_row, new_col, new_keys, steps + 1))

    # If exit is unreachable
    return -1

