            index_map = {}
            current = v
            while True:
                if visited[current]:
                    if current in index_map:
                        cycle_start = index_map[current]
                        cycle = path[cycle_start:]
                        cycle_length = len(cycle)
                        for node in cycle:
                            result[node] = (0, cycle_length)
                            visited[node] = True
                        for i in reversed(range(cycle_start)):
                            node = path[i]
                            next_node = path[i + 1]
                            result[node] = (result[next_node][0] + 1, result[next_node][1])
                            visited[node] = True
                    else:
                        for i in reversed(range(len(path))):
                            node = path[i]
                            if i == len(path) - 1:
                                next_node = current
                            else:
                                next_node = path[i + 1]
                            result[node] = (result[next_node][0] + 1, result[next_node][1])
