    return isinstance(x, int) and not isinstance(x, bool)

def min_drops(eggs, floors):
    if not is_valid(eggs) or not is_valid(floors):
        raise ValueError
    if eggs < 1 or eggs > 64 or floors < 0 or floors > 10**18:
        raise ValueError
    if floors == 0:
        return 0
    if eggs == 1:
        return floors
    low = 1
    high = 1
    while compute_max_floors(high, eggs, floors) < floors:
        high *= 2
    result = high
    while low <= high:
        mid = (low + high) // 2
        current = compute_max_floors(mid, eggs, floors)
        if current >= floors:
            result = mid
            high = mid - 1
        else:
            low = mid + 1
    return result

def first_drop(eggs, floors):
    if not is_valid(eggs) or not is_valid(floors):
        raise ValueError
    if eggs < 1 or eggs > 64 or floors < 1 or floors > 10**18:
        raise ValueError
    t = min_drops(eggs, floors)
    e = eggs
    a = compute_max_floors(t - 1, e - 1, floors)
    return a + 1

def interleave_count(a, b, c):
    if not (isinstance(a, str) and isinstance(b, str) and isinstance(c, str)):
        raise ValueError
    len_a = len(a)
    len_b = len(b)
    len_c = len(c)
    if len_a > 300 or len_b > 300:
        raise ValueError
    if len_c != len_a + len_b:
        return 0

    dp = [[0] * (len_b + 1) for _ in range(len_a + 1)]
    dp[0][0] = 1

    for i in range(len_a + 1):
        for j in range(len_b + 1):
            if i == 0 and j == 0:
                continue
            current_pos = i + j - 1
            if current_pos >= len_c:
                continue
            current_char = c[current_pos]
            if i > 0 and a[i-1] == current_char:
                dp[i][j] += dp[i-1][j]
            if j > 0 and b[j-1] == current_char:
                dp[i][j] += dp[i][j-1]

    return dp[len_a][len_b]

def interleave_labels(a, b, c):
    if not (isinstance(a, str) and isinstance(b, str) and isinstance(c, str)):
        raise ValueError
    len_a = len(a)
    len_b = len(b)
    len_c = len(c)
    if len_a > 300 or len_b > 300:
        raise ValueError
    if len_c != len_a + len_b:
        return None

    possible = [[False] * (len_b + 1) for _ in range(len_a + 1)]
    possible[len_a][len_b] = True

    for i in range(len_a, -1, -1):
        for j in range(len_b, -1, -1):
            if i == len_a and j == len_b:
                continue
            current_pos = i + j
            if current_pos >= len_c:
                possible[i][j] = False
                continue
            current_char = c[current_pos]
            if i < len_a and a[i] == current_char and possible[i+1][j]:
                possible[i][j] = True
            if j < len_b and b[j] == current_char and possible[i][j+1]:
                possible[i][j] = possible[i][j] or True

    if not possible[0][0]:
        return None

    labels = []
    i, j = 0, 0
    for k in range(len_c):
        current_char = c[k]
        if i < len_a and a[i] == current_char and possible[i+1][j]:
            labels.append('A')
            i += 1
        else:
            if j < len_b and b[j] == current_char and possible[i][j+1]:
                labels.append('B')
                j += 1
            else:
                return None
    return ''.join(labels)

