    if not isinstance(rule, str) or len(rule) < 2 or len(rule) > 12:
        raise ValueError
    if not all(c in ('L', 'R') for c in rule):
        raise ValueError
    if not isinstance(steps, int) or isinstance(steps, bool) or steps < 0 or steps > 10**5:
        raise ValueError

