        grid[(x, y)] = new_color
        # Move
        if direction == 0:
            y += 1
        elif direction == 1:
            x += 1
        elif direction == 2:
            y -= 1
        else:
            x -= 1

    # Collect non-zero cells
    non_zero = {pos: color for pos, color in grid.items() if color != 0}
    if not non_zero:
        return []

    # Find min and max x and y
    xs = [pos[0] for pos in non_zero.keys()]
    ys = [pos[1] for pos in non_zero.keys()]
    min_x, max_x = min(xs), max(xs)
    min_y, max_y = min(ys), max(ys)

    # Generate the grid
    rows = []
    for y_val in range(max_y, min_y - 1, -1):
        row = []
        for x_val in range(min_x, max_x + 1):
            color = non_zero.get((x_val, y_val), 0)
            if color != 0:
                if color <= 9:
                    row_char = str(color)
                else:
                    row_char = chr(ord('a') + (color - 10))
                row.append(row_char)
            else:
                row.append('0')
        rows.append(''.join(row))

    # Check if any row is empty; if so, return []
    if all(len(row) == 0 for row in rows):
        return []

    return rows

