                raise ValueError

    # Make a deep copy of the grid
    stable_grid = [row.copy() for row in grid]
    count = 0

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    queue = deque()
    queue_set = set()

    # Initialize the queue with all unstable cells
    for i in range(rows):
        for j in range(cols):
