        if stable_grid[i][j] < 4:
            continue

        times = stable_grid[i][j] // 4
        count += times
        stable_grid[i][j] -= 4 * times

        for di, dj in directions:
            ni, nj = i + di, j + dj
            if 0 <= ni < rows and 0 <= nj < cols:
