            raise ValueError
        row, col = cell
        if type(row) is not int or type(col) is not int:
            raise ValueError
        if row < 0 or row >= height or col < 0 or col >= width:
            raise ValueError

    # Validate moves
    for c in moves:
        if c not in {'U', 'D', 'L', 'R'}:
