def realize_gains(trades, method):
    if method not in ('fifo', 'lifo'):
        raise ValueError("Invalid method")

    gain = 0
    lots = []

    for trade in trades:
        if not isinstance(trade, (list, tuple)) or len(trade) != 3:
            raise ValueError("Invalid trade")

        kind, qty, price = trade

        if kind not in ('buy', 'sell'):
            raise ValueError("Invalid trade kind")

        if type(qty) is not int or qty < 1:
            raise ValueError("Invalid quantity")

        if type(price) is not int or price < 0:
            raise ValueError("Invalid price")

        if kind == 'buy':
            lots.append([qty, price])
        else:
            total_available = sum(lot[0] for lot in lots)
            if total_available < qty:
                raise ValueError("Not enough shares to sell")

            if method == 'fifo':
                order = lots.copy()
            else:
                order = lots[::-1].copy()

            required = qty
            for lot in order:
                if required <= 0:
                    break
                if lot[0] == 0:
                    continue

                take = min(lot[0], required)
                gain += take * (price - lot[1])
                lot[0] -= take

                if lot[0] == 0:
                    try:
                        index = lots.index(lot)
                        del lots[index]
                    except ValueError:
                        pass  # This should not happen as lot is in lots initially

                required -= take

    lots = [tuple(lot) for lot in lots]
    return (gain, lots)

