def min_jumps(lengths):
    if not isinstance(lengths, list):
        raise ValueError
    for num in lengths:
        if not isinstance(num, int) or isinstance(num, bool):
            raise ValueError
        if num < 0:
            raise ValueError
    n = len(lengths)
    if n == 0:
        raise ValueError
    if n == 1:
        return 0

    current_max = 0
    next_max = 0
    jumps = 0

    for i in range(n):
        if i > current_max:
            return -1
        next_max = max(next_max, i + lengths[i])
        if i == current_max:
            jumps += 1
            current_max = next_max
            if current_max >= n - 1:
                break
    if current_max >= n - 1:
        return jumps
    else:
        return -1

def farthest_after(lengths, k):
    if not isinstance(lengths, list):
        raise ValueError
    for num in lengths:
        if not isinstance(num, int) or isinstance(num, bool):
            raise ValueError
        if num < 0:
            raise ValueError
    n = len(lengths)
    if n == 0:
        raise ValueError

    if not isinstance(k, int) or isinstance(k, bool):
        raise ValueError
    if k < 0:
        raise ValueError

    if k == 0:
        return 0

    current_max = 0
    next_max = 0
    jumps = 0

    for i in range(n):
        if i > current_max:
            break
        next_max = max(next_max, i + lengths[i])
        if i == current_max:
            jumps += 1
            if jumps > k:
                break
            current_max = next_max
            if current_max >= n - 1:
                break
    return min(current_max, n - 1)

